import React, { useState, useEffect, useRef, useCallback } from 'react';
import { Play, Pause, Square, RotateCcw, Volume2, Save, Share } from 'lucide-react';
import * as Tone from 'tone';
import useFiles from "./hooks/useFiles";
import dayjs from 'dayjs';

const GuitarChordApp = () => {

  const files = useFiles();
  const { getFileByName, saveFileByName } = files;


  const [isPlaying, setIsPlaying] = useState(false);
  const [currentCell, setCurrentCell] = useState({ row: -1, col: -1 });
  const [selectedCell, setSelectedCell] = useState({ row: 0, col: 0 });
  const [tempo, setTempo] = useState(120);
  const [volume, setVolume] = useState(0.5);
  const [isAudioReady, setIsAudioReady] = useState(false);
  const [audioStatus, setAudioStatus] = useState('Not initialized');
  const [globalMessage, setGlobalMessage] = useState(null);
  const [globalError, setGlobalError] = useState("");
  const [globalWarning, setGlobalWarning] = useState('Initalize audio');
  const [numRows, setNumRows] = useState(1);
  const [numCols, setNumCols] = useState(4);
  const [grid, setGrid] = useState(() => {
    // Initialize 1x4 grid with empty cells (default to 1 row)
    return Array(numRows).fill(null).map(() =>
      Array(numCols).fill(null).map(() => ({ chord: '', pattern: null }))
    );
  });
  const [currentFile, setCurrentFile] = useState(null);
  const [savedCustomPatterns, setSavedCustomPatterns] = useState(() => {
    // Load saved patterns from localStorage on initialization
    try {
      const saved = localStorage.getItem('guitarApp_customPatterns');
      return saved ? JSON.parse(saved) : {};
    } catch (error) {
      console.error('Error loading saved patterns:', error);
      return {};
    }
  });
  const [needsSave, setNeedsSave] = useState(false);
  const [shareLink, setShareLink] = useState('');

  const intervalRef = useRef(null);
  const synthRef = useRef(null);
  const reverbRef = useRef(null);

  const clearProblems = useCallback(() => {
    setGlobalError(null);
    setGlobalWarning(null);
  }, [setGlobalWarning, setGlobalError]);

  const needsSaving = () => {
    setNeedsSave(true);
    setShareLink("");
  }

  // Comprehensive guitar chords with their fingerings (MIDI note numbers)
  // All major, minor, and 7th chords for all 12 keys
  const chords = {
    // C Family
    'C': [48, 52, 55, 60, 64, 67],      // C major
    'Cm': [48, 51, 55, 60, 63, 67],     // C minor
    'C7': [48, 52, 55, 58, 64, 67],     // C dominant 7th

    // C# / Db Family
    'C#': [49, 53, 56, 61, 65, 68],     // C# major
    'C#m': [49, 52, 56, 61, 64, 68],    // C# minor
    'C#7': [49, 53, 56, 59, 65, 68],    // C# dominant 7th
    'Db': [49, 53, 56, 61, 65, 68],     // Db major (enharmonic)
    'Dbm': [49, 52, 56, 61, 64, 68],    // Db minor
    'Db7': [49, 53, 56, 59, 65, 68],    // Db dominant 7th

    // D Family
    'D': [38, 45, 50, 54, 57, 62],      // D major
    'Dm': [38, 45, 50, 53, 57, 62],     // D minor
    'D7': [38, 45, 50, 52, 57, 62],     // D dominant 7th

    // D# / Eb Family
    'D#': [39, 46, 51, 55, 58, 63],     // D# major
    'D#m': [39, 46, 51, 54, 58, 63],    // D# minor
    'D#7': [39, 46, 51, 53, 58, 63],    // D# dominant 7th
    'Eb': [39, 46, 51, 55, 58, 63],     // Eb major (enharmonic)
    'Ebm': [39, 46, 51, 54, 58, 63],    // Eb minor
    'Eb7': [39, 46, 51, 53, 58, 63],    // Eb dominant 7th

    // E Family
    'E': [40, 47, 52, 56, 59, 64],      // E major
    'Em': [40, 47, 52, 55, 59, 64],     // E minor
    'E7': [40, 47, 52, 54, 59, 64],     // E dominant 7th

    // F Family
    'F': [41, 45, 48, 53, 57, 60],      // F major
    'Fm': [41, 44, 48, 53, 56, 60],     // F minor
    'F7': [41, 45, 48, 51, 57, 60],     // F dominant 7th

    // F# / Gb Family
    'F#': [42, 46, 49, 54, 58, 61],     // F# major
    'F#m': [42, 45, 49, 54, 57, 61],    // F# minor
    'F#7': [42, 46, 49, 52, 58, 61],    // F# dominant 7th
    'Gb': [42, 46, 49, 54, 58, 61],     // Gb major (enharmonic)
    'Gbm': [42, 45, 49, 54, 57, 61],    // Gb minor
    'Gb7': [42, 46, 49, 52, 58, 61],    // Gb dominant 7th

    // G Family
    'G': [43, 47, 50, 55, 59, 67],      // G major
    'Gm': [43, 46, 50, 55, 58, 67],     // G minor
    'G7': [43, 47, 50, 53, 59, 67],     // G dominant 7th

    // G# / Ab Family
    'G#': [44, 48, 51, 56, 60, 68],     // G# major
    'G#m': [44, 47, 51, 56, 59, 68],    // G# minor
    'G#7': [44, 48, 51, 54, 60, 68],    // G# dominant 7th
    'Ab': [44, 48, 51, 56, 60, 68],     // Ab major (enharmonic)
    'Abm': [44, 47, 51, 56, 59, 68],    // Ab minor
    'Ab7': [44, 48, 51, 54, 60, 68],    // Ab dominant 7th

    // A Family
    'A': [45, 52, 57, 61, 64, 69],      // A major
    'Am': [45, 52, 57, 60, 64, 69],     // A minor
    'A7': [45, 52, 57, 59, 64, 69],     // A dominant 7th

    // A# / Bb Family
    'A#': [46, 53, 58, 62, 65, 70],     // A# major
    'A#m': [46, 53, 58, 61, 65, 70],    // A# minor
    'A#7': [46, 53, 58, 60, 65, 70],    // A# dominant 7th
    'Bb': [46, 53, 58, 62, 65, 70],     // Bb major (enharmonic)
    'Bbm': [46, 53, 58, 61, 65, 70],    // Bb minor
    'Bb7': [46, 53, 58, 60, 65, 70],    // Bb dominant 7th

    // B Family
    'B': [35, 42, 47, 51, 54, 59],      // B major
    'Bm': [35, 42, 47, 50, 54, 59],     // B minor
    'B7': [35, 42, 47, 49, 54, 59]      // B dominant 7th
  };

  // Common picking patterns
  const pickingPatterns = {
    'p-i-m-a': [0, 1, 2, 3], // thumb, index, middle, ring
    'p-i-m-i': [0, 1, 2, 1],
    'p-m-i-m': [0, 2, 1, 2],
    'p-i-p-m': [0, 1, 0, 2],
    'p-a-m-i': [0, 3, 2, 1],
    'travis': [0, 2, 1, 2, 0, 3, 1, 3], // Travis picking
    'arpeggio': [0, 1, 2, 3, 2, 1], // Classic arpeggio
    'custom': [] // For user-created patterns
  };

  const stringNames = ['E (lo)', 'A', 'D', 'G', 'B', 'E (hi)'];

  // Initialize audio context and synth
  const initializeAudio = async () => {
    try {
      setAudioStatus('Initializing...');
      clearProblems();

      // Start the audio context
      await Tone.start();
      setAudioStatus('Audio context started');
      clearProblems();

      // Create a guitar-like synth
      synthRef.current = new Tone.PolySynth(Tone.Synth, {
        oscillator: {
          type: 'triangle'
        },
        envelope: {
          attack: 0.01,
          decay: 0.8,
          sustain: 0.2,
          release: 1.5
        },
        volume: -8
      });

      // Add reverb for a more natural sound
      reverbRef.current = new Tone.Reverb({
        decay: 1.5,
        preDelay: 0.01,
        wet: 0.2
      });

      setAudioStatus('Creating reverb...');
      await reverbRef.current.generate();

      synthRef.current.chain(reverbRef.current, Tone.Destination);

      setIsAudioReady(true);
      setAudioStatus('Ready!');

      // Test sound
      setTimeout(() => {
        if (synthRef.current) {
          synthRef.current.triggerAttackRelease('C4', '8n');
          setAudioStatus('Ready! (Test sound played)');
        }
      }, 100);

    } catch (error) {
      console.error('Error initializing audio:', error);
      setAudioStatus(`Error: ${error.message}`);
    }
  };

  const midiToFreq = (midi) => {
    return 440 * Math.pow(2, (midi - 69) / 12);
  };

  const playChordNote = async (chordName, stringIndex, duration = '8n') => {
    if (!isAudioReady || !synthRef.current || !chordName || !chords[chordName]) return;

    try {
      if (Tone.context.state !== 'running') {
        await Tone.start();
      }

      const chordNotes = chords[chordName];
      if (stringIndex < chordNotes.length) {
        const freq = midiToFreq(chordNotes[stringIndex]);
        synthRef.current.triggerAttackRelease(freq, duration);
      }
    } catch (error) {
      console.error('Error playing note:', error);
    }
  };

  const updateCell = (row, col, field, value) => {
    const newGrid = [...grid];
    newGrid[row][col] = { ...newGrid[row][col], [field]: value };
    setGrid(newGrid);

    // Auto-advance to next cell when a chord is selected
    if (field === 'chord' && value !== '') {
      advanceToNextCell(row, col);
    }

    needsSaving();
  };

  const updateCustomPattern = (row, col, newPattern, patternName = null) => {
    const newGrid = [...grid];
    newGrid[row][col] = {
      ...newGrid[row][col],
      pattern: 'custom',
      customPattern: newPattern,
      customPatternName: patternName
    };
    setGrid(newGrid);
    needsSaving();
  };

  const addToCustomPattern = (stringIndex) => {
    const currentCell = grid[selectedCell.row][selectedCell.col];
    const currentPattern = currentCell.customPattern || [];
    const newPattern = [...currentPattern, stringIndex];
    updateCustomPattern(selectedCell.row, selectedCell.col, newPattern, currentCell.customPatternName);
    needsSaving();
  };

  const clearCustomPattern = () => {
    updateCustomPattern(selectedCell.row, selectedCell.col, [], null);
    needsSaving();
  };

  const saveCustomPattern = (name, pattern) => {
    if (!name.trim() || pattern.length === 0) return;

    const newSavedPatterns = {
      ...savedCustomPatterns,
      [name.trim()]: pattern
    };

    setSavedCustomPatterns(newSavedPatterns);

    // Persist to localStorage
    try {
      localStorage.setItem('guitarApp_customPatterns', JSON.stringify(newSavedPatterns));
    } catch (error) {
      console.error('Error saving pattern:', error);
    }
  };

  const deleteCustomPattern = (name) => {
    const newSavedPatterns = { ...savedCustomPatterns };
    delete newSavedPatterns[name];
    setSavedCustomPatterns(newSavedPatterns);

    // Persist to localStorage
    try {
      localStorage.setItem('guitarApp_customPatterns', JSON.stringify(newSavedPatterns));
    } catch (error) {
      console.error('Error deleting pattern:', error);
    }
  };

  const loadCustomPattern = (pattern, patternName) => {
    updateCustomPattern(selectedCell.row, selectedCell.col, pattern, patternName);
  };

  const getCurrentPattern = (cell) => {
    if (cell.pattern === 'custom') {
      return cell.customPattern || [];
    }
    return pickingPatterns[cell.pattern] || [];
  };

  const advanceToNextCell = (currentRow, currentCol) => {
    let nextCol = currentCol + 1;
    let nextRow = currentRow;

    if (nextCol >= 4) {
      nextCol = 0;
      nextRow = currentRow + 1;

      if (nextRow >= numRows) {
        nextRow = 0;
      }
    }

    setSelectedCell({ row: nextRow, col: nextCol });
  };

  const playCell = async (row, col) => {
    const cell = grid[row][col];
    if (!cell.chord) return;

    const pattern = getCurrentPattern(cell);
    if (!pattern || pattern.length === 0) return;

    const noteDuration = (60 / tempo) / pattern.length;

    for (let i = 0; i < pattern.length; i++) {
      setTimeout(() => {
        playChordNote(cell.chord, pattern[i], `${noteDuration}s`);
      }, i * noteDuration * 1000);
    }
  };

  const playSequence = async () => {
    if (!isAudioReady) {
      await initializeAudio();
      if (!isAudioReady) {
        alert('Please click "Initialize Audio" first!');
        return;
      }
    }

    if (Tone.context.state !== 'running') {
      await Tone.start();
    }

    if (isPlaying) {
      clearInterval(intervalRef.current);
      setIsPlaying(false);
      setCurrentCell({ row: -1, col: -1 });
      return;
    }

    setIsPlaying(true);
    const cellDuration = (60 / tempo) * 1000;
    let row = 0, col = 0;

    const playNext = () => {
      setCurrentCell({ row, col });
      playCell(row, col);

      col++;
      if (col >= 4) {
        col = 0;
        row++;
        if (row >= numRows) {
          row = 0;
        }
      }
    };

    playNext();
    intervalRef.current = setInterval(playNext, cellDuration);
  };

  const stopPlayback = () => {
    clearInterval(intervalRef.current);
    setIsPlaying(false);
    setCurrentCell({ row: -1, col: -1 });
  };

  const resetGrid = () => {
    stopPlayback();
    setGrid(Array(numRows).fill(null).map(() =>
      Array(4).fill(null).map(() => ({ chord: '', pattern: 'p-i-m-a' }))
    ));
  };

  const getSerializedState = () => {
    const fileName = currentFile?.name;
    return {
      grid,
      numRows,
      numCols,
      fileName,
      tempo,
      volume,
    };
  };

  const loadFile = async (fileName) => {
    try {
      const file = await getFileByName(fileName);
      if (!file) {
        alert("no file with id " + fileName);
        return;
      }
      setCurrentFile(file);
      const stringContent = await file.blob.text();
      const content = JSON.parse(stringContent);
      const {
        grid,
        numRows,
        numCols,
        tempo,
        volume,
      } = content;
      setGrid(grid);
      setNumRows(numRows);
      setNumCols(numCols);
      setTempo(tempo);
      setVolume(volume);
    } catch (e) {
      alert(e);
    }
  };

  const saveCurrentFile = async () => {
    let cur = currentFile?.name;
    if (!cur) {
      const f = prompt("Enter a name for this file:");
      cur = f;
    }

    const serializedState = getSerializedState();
    const newFile = await saveFileByName({ fileName: cur, content: serializedState });
    const { file } = newFile;
    console.log("newFile", newFile);

    const urlParams = new URLSearchParams(window.location.search);
    urlParams.set('f', cur);
    window.history.replaceState({}, '', `${window.location.pathname}?${urlParams}`);

    needsSaving();
    setCurrentFile(file);
  };

  const share = async () => {
    const serializedState = getSerializedState();
    const serializedStateString = JSON.stringify(serializedState);
    const encodedState = encodeURIComponent(serializedStateString);

    const urlParams = new URLSearchParams(window.location.search);
    urlParams.set('c', encodedState);
    window.history.replaceState({}, '', `${window.location.pathname}?${urlParams}`);

    setShareLink(`${window.location.origin}${window.location.pathname}?${urlParams}`);
  };

  const loadSerializedContent = async (serializedContentString) => {
    const decodedContent = decodeURIComponent(serializedContentString);
    const content = JSON.parse(decodedContent);
    const {
      grid,
      numRows,
      numCols,
      tempo,
      volume,
    } = content;
    setGrid(grid);
    setNumRows(numRows);
    setNumCols(numCols);
    setTempo(tempo);
    setVolume(volume);
  }

  const updateNumRows = (newNumRows) => {
    const numRowsInt = parseInt(newNumRows);
    setNumRows(numRowsInt);

    const newGrid = Array(numRowsInt).fill(null).map((_, rowIndex) =>
      Array(numCols).fill(null).map((_, colIndex) => {
        if (grid[rowIndex] && grid[rowIndex][colIndex]) {
          return grid[rowIndex][colIndex];
        }
        return { chord: '', pattern: 'p-i-m-a' };
      })
    );

    setGrid(newGrid);

    if (selectedCell.row >= numRowsInt) {
      setSelectedCell({ row: 0, col: 0 });
    }

    if (isPlaying) {
      stopPlayback();
    }

    needsSaving();
  };

  const updateNumCols = (newNumCols) => {
    const numColsInt = parseInt(newNumCols);
    setNumCols(numColsInt);

    const newGrid = grid.map(row => {
      const newRow = [...row];
      while (newRow.length < numColsInt) {
        newRow.push({ chord: '', pattern: 'p-i-m-a' });
      }
      return newRow.slice(0, numColsInt);
    });

    setGrid(newGrid);

    if (selectedCell.col >= numColsInt) {
      setSelectedCell({ row: selectedCell.row, col: 0 });
    }

    if (isPlaying) {
      stopPlayback();
    }

    needsSaving();

  }

  useEffect(() => {
    if (synthRef.current) {
      synthRef.current.volume.value = Tone.gainToDb(volume);
    }
  }, [volume]);

  useEffect(() => {
    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }
      if (synthRef.current) {
        synthRef.current.dispose();
      }
      if (reverbRef.current) {
        reverbRef.current.dispose();
      }
    };
  }, []);

  useEffect(() => {
    // If the f url param is set, load that file
    const urlParams = new URLSearchParams(window.location.search);
    const f = urlParams.get('f');
    if (f) {
      loadFile(f);
      return;
    }
    const c = urlParams.get('c');
    if (c) {
      loadSerializedContent(c);
      return;
    }
  }, []);

  const getCellClass = (row, col) => {
    let baseClass = "border-2 border-gray-300 p-2 min-h-20 cursor-pointer transition-all duration-200 ";

    if (currentCell.row === row && currentCell.col === col) {
      baseClass += "bg-green-200 border-green-500 shadow-lg ";
    } else if (selectedCell.row === row && selectedCell.col === col) {
      baseClass += "bg-blue-100 border-blue-400 ";
    } else {
      baseClass += "bg-white hover:bg-gray-50 ";
    }

    return baseClass;
  };

  const ControlButtons = () => {
    return <div className="flex flex-row">
      <button
        onClick={playSequence}
        className="flex items-center gap-2 px-6 py-3 bg-green-500 hover:bg-green-600 text-white rounded-lg font-semibold transition-colors"
      >
        {isPlaying ? <Pause size={20} /> : <Play size={20} />}
      </button>

      <button
        onClick={stopPlayback}
        className="flex items-center gap-2 px-6 py-3 bg-red-500 hover:bg-red-600 text-white rounded-lg font-semibold transition-colors"
      >
        <Square size={20} />
      </button>

      <button
        onClick={resetGrid}
        className="flex items-center gap-2 px-6 py-3 bg-gray-500 hover:bg-gray-600 text-white rounded-lg font-semibold transition-colors"
      >
        <RotateCcw size={20} />
      </button>

      <button
        onClick={saveCurrentFile}
        className="flex items-center gap-2 px-6 py-3 bg-yellow-500 hover:bg-red-600 text-white rounded-lg font-semibold transition-colors ml-2 mr-1"
      >
        <Save size={20} disabled={!currentFile || !needsSave} />
      </button>
      <button
        onClick={share}
        className="flex items-center gap-2 px-6 py-3 bg-purple-500 hover:bg-red-600 text-white rounded-lg font-semibold transition-colors ml-2 mr-1"
      >
        <Share size={20} />
      </button>
    </div>;
  }

  const PlayerState = () => {
    const cellDuration = (60 / tempo);
    const pattern = currentCell.row >= 0 && currentCell.col >= 0
      ? getCurrentPattern(grid[currentCell.row][currentCell.col])
      : [];
    const beatCount = pattern.length || 1;
    const currentBeat = isPlaying && currentCell.row >= 0 && currentCell.col >= 0
      ? ((Date.now() / 1000 / cellDuration) % beatCount | 0) + 1
      : 0;

    let lastUpdatedFormatted = '';
    if (currentFile) {
      lastUpdatedFormatted = dayjs(currentFile.updated).format('MMM D, YYYY h:mm A');
    }

    return (
      <div className="mt-2 text-sm text-gray-700">
        {currentFile &&
          <>
            <span className="font-semibold">File:</span> {currentFile.name} ({lastUpdatedFormatted}) &nbsp;|&nbsp;
          </>
        }
        {isPlaying && currentCell.row >= 0 && currentCell.col >= 0 ? (
          <span>
            <span className="font-semibold">Cell:</span> {currentCell.row + 1}.{currentCell.col + 1} &nbsp;|&nbsp;
            <span className="font-semibold">Beat:</span> {currentBeat} / {beatCount}
          </span>
        ) : (
          <span>Not playing</span>
        )}
      </div>
    );
  }

  const StatusMessages = () => {
    return <div className="flex flex-col text- text-gray-700">
      <div>
        <span className={`font-medium ${isAudioReady ? 'text-green-600' : 'text-orange-600'}`}>
          {audioStatus}
        </span>
        {globalMessage && <span className={`font-medium text-blue-600`}>
          {globalMessage}
        </span>}
        {globalError && <span className={`font-medium text-red-600`}>
          Error: {globalError}
        </span>}
        {globalWarning && <span className={`font-medium text-orange-600`}>
          Warning: {globalWarning}
        </span>}
      </div>
      <div>
        {shareLink &&
          <a href={shareLink} target="_blank" rel="noreferrer" className="font-medium text-blue-600">
            Share 🔗
          </a>}
      </div>
    </div>;
  }

  const NumColsSelector = () => {
    return <><div className="flex items-center gap-2">
      <label className="text-gray-700 font-medium">Cols:</label>
      <select
        value={numCols}
        onChange={(e) => updateNumCols(e.target.value)}
        className="px-3 py-2 border border-gray-300 rounded-lg bg-white text-gray-700 font-medium"
      >
        <option value={1}>1</option>
        <option value={2}>2</option>
        <option value={3}>3</option>
        <option value={4}>4</option>
        <option value={5}>5</option>
        <option value={6}>6</option>
        <option value={7}>7</option>
        <option value={8}>8</option>
      </select>
    </div>
      <div>
        <button
          onClick={() => updateNumCols(numCols + 1)}
          className="px-4 py-2 bg-blue-400 hover:bg-blue-500 text-white rounded-lg font-semibold mr-2"
          disabled={numCols >= 8}
        >
          +
        </button>
        <button
          onClick={() => updateNumCols(Math.max(1, numCols - 1))}
          className="px-4 py-2 bg-red-400 hover:bg-red-500 text-white rounded-lg font-semibold"
          disabled={numCols <= 1}
        >
          −
        </button>
      </div>
    </>;
  }

  const NumRowsSelector = () => {
    return <><div className="flex items-center gap-2">
      <label className="text-gray-700 font-medium">Rows:</label>
      <select
        value={numRows}
        onChange={(e) => updateNumRows(e.target.value)}
        className="px-3 py-2 border border-gray-300 rounded-lg bg-white text-gray-700 font-medium"
      >
        <option value={1}>1</option>
        <option value={2}>2</option>
        <option value={3}>3</option>
        <option value={4}>4</option>
        <option value={5}>5</option>
        <option value={6}>6</option>
        <option value={7}>7</option>
        <option value={8}>8</option>
      </select>
    </div>
      <div>
        <button
          onClick={() => updateNumRows(numRows + 1)}
          className="px-4 py-2 bg-blue-400 hover:bg-blue-500 text-white rounded-lg font-semibold mr-2"
          disabled={numRows >= 8}
        >
          +
        </button>
        <button
          onClick={() => updateNumRows(Math.max(1, numRows - 1))}
          className="px-4 py-2 bg-red-400 hover:bg-red-500 text-white rounded-lg font-semibold"
          disabled={numRows <= 1}
        >
          −
        </button>
      </div>
    </>;
  }

  return (
    <div className="max-w-6xl mx-auto p-6 bg-gradient-to-br from-blue-50 to-indigo-100 min-h-screen">

      {/* Controls */}
      <div className="bg-white rounded-xl shadow-lg p-6 mb-8">
        {/* Audio Initialization */}
        <div className="p-4 bg-gray-50 rounded-lg">
          <div className="flex items-center gap-4 mb-3">
            <div className="flex flex-row w-full justify-between">
              <div className="flex flex-row">
                <ControlButtons />
                &nbsp;
                <StatusMessages />
              </div>
              <div className="flex flex-end justify-end">
                <button
                  onClick={initializeAudio}
                  className="px-6 py-3 bg-blue-500 hover:bg-blue-600 text-white rounded-lg font-semibold transition-colors"
                >
                  Init Audio
                </button>
              </div>
            </div>
          </div>
          <PlayerState />
        </div>

        <div className="flex items-center gap-4">
          <label className="flex items-center gap-2 text-gray-700 font-medium">
            <Volume2 size={18} />
            Tempo:
          </label>
          <input
            type="range"
            min="60"
            max="180"
            value={tempo}
            onChange={(e) => setTempo(parseInt(e.target.value))}
            className="w-full"
          />
          <span className="text-gray-700 font-medium">{tempo} BPM</span>

          <label className="flex items-center gap-2 text-gray-700 font-medium ml-8">
            Volume:
          </label>
          <input
            type="range"
            min="0"
            max="1"
            step="0.1"
            value={volume}
            onChange={(e) => setVolume(parseFloat(e.target.value))}
            className="w-full"
          />
          <span className="text-gray-700 font-medium">{Math.round(volume * 100)}%</span>
        </div>
      </div>

      {/* Grid */}
      <div className="bg-white rounded-xl shadow-lg p-6 mb-8">
        <h2 className="text-2xl font-bold text-gray-800 mb-4">
          Chord Grid ({numRows} row{numRows !== 1 ? 's' : ''} × 4 columns)
        </h2>
        <div className="flex flex-wrap items-center gap-4 mb-4 w-full" >
          <NumColsSelector />
          <NumRowsSelector />
        </div>
        <div className="grid grid-cols-4 gap-2 mb-6">
          {grid.map((row, rowIndex) =>
            row.map((cell, colIndex) => (
              <div
                key={`${rowIndex}-${colIndex}`}
                className={getCellClass(rowIndex, colIndex)}
                onClick={() => setSelectedCell({ row: rowIndex, col: colIndex })}
                onDoubleClick={() => playCell(rowIndex, colIndex)}
                style={{ position: 'relative' }}
              >
                {/* Upper right info */}
                <div
                  style={{
                    position: 'absolute',
                    top: 6,
                    right: 8,
                    textAlign: 'right',
                    zIndex: 2,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'flex-end',
                    minHeight: '20px',
                    gap: '4px'
                  }}
                >
                  <div className="text-xs text-gray-600 font-mono">
                    {cell.pattern === 'custom'
                      ? (cell.customPatternName || `Custom (${(cell.customPattern || []).length})`)
                      : cell.pattern
                    }
                    {!cell.chord && (
                      <span className="ml-2 px-2 py-1 bg-red-100 text-red-700 text-xs rounded-full font-semibold align-middle">
                        <span className="text-red-500">C</span>
                      </span>
                    )}
                  </div>
                  <div style={{ marginLeft: 2 }}>
                    {!cell.pattern && (
                      <span className="px-2 py-1 bg-yellow-100 text-yellow-700 text-xs rounded-full font-semibold align-middle">
                        <span className="text-red-500">P</span>
                      </span>
                    )}
                  </div>
                </div>
                <div className="text-center pt-2">
                  <div className="text-xl font-bold text-gray-800 mb-1">
                    {cell.chord || `${rowIndex + 1}.${colIndex + 1}`}
                  </div>
                </div>
                {/* Cell Pattern Visualization */}
                <div className="mt-2 flex flex-row">
                  <div className="bg-gray-50 rounded-lg p-2 overflow-x-auto">
                    <div className="min-w-48">
                      {[...stringNames].reverse().map((stringName, stringIndex) => (
                        <div key={stringIndex} className="flex items-center mb-1">
                          <div className="w-8 text-xs font-medium text-gray-700 text-right mr-2">
                            {stringName}
                          </div>
                          <div className="flex-1 relative">
                            <div className="h-1 bg-amber-400 relative">
                              {getCurrentPattern(cell).map((playedString, noteIndex) => {
                                const reversedIndex = stringNames.length - 1 - playedString;
                                if (reversedIndex === stringIndex) {
                                  const totalNotes = getCurrentPattern(cell).length;
                                  const maxSlots = Math.max(8, totalNotes);
                                  const position = (noteIndex / Math.max(1, maxSlots - 1)) * 100;
                                  return (
                                    <div
                                      key={noteIndex}
                                      className="absolute w-4 h-4 bg-blue-900 border-2 border-white rounded-full shadow transform -translate-y-1/2 -translate-x-1/2 flex items-center justify-center"
                                      style={{ left: `${Math.min(position, 95)}%`, top: '50%' }}
                                      title={`Note ${noteIndex + 1}: ${stringName}`}
                                    >
                                      <span className="text-[10px] text-white font-bold">{noteIndex + 1}</span>
                                    </div>
                                  );
                                }
                                return null;
                              })}
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            )
            )
          )}
        </div>
      </div>

      {/* Chord and Pattern Selection */}
      <div className="grid md:grid-cols-2 gap-6">
        {/* Chord Selection - DROPDOWN */}
        <div className="bg-white rounded-xl shadow-lg p-6">
          <h3 className="text-xl font-bold text-gray-800 mb-4">
            Select Chord for Cell {selectedCell.row + 1}.{selectedCell.col + 1}
          </h3>

          <div className="mb-4">
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Choose Chord:
            </label>
            <select
              value={grid[selectedCell.row][selectedCell.col].chord}
              onChange={(e) => updateCell(selectedCell.row, selectedCell.col, 'chord', e.target.value)}
              className="w-full p-3 border border-gray-300 rounded-lg bg-white text-gray-800 font-semibold focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-blue-500 text-lg"
            >
              <option value="">-- Select Chord --</option>

              <optgroup label="C / C# Family">
                <option value="C">C major</option>
                <option value="Cm">C minor</option>
                <option value="C7">C7</option>
                <option value="C#">C# major</option>
                <option value="C#m">C# minor</option>
                <option value="C#7">C#7</option>
                <option value="Db">Db major</option>
                <option value="Dbm">Db minor</option>
                <option value="Db7">Db7</option>
              </optgroup>

              <optgroup label="D / D# Family">
                <option value="D">D major</option>
                <option value="Dm">D minor</option>
                <option value="D7">D7</option>
                <option value="D#">D# major</option>
                <option value="D#m">D# minor</option>
                <option value="D#7">D#7</option>
                <option value="Eb">Eb major</option>
                <option value="Ebm">Eb minor</option>
                <option value="Eb7">Eb7</option>
              </optgroup>

              <optgroup label="E Family">
                <option value="E">E major</option>
                <option value="Em">E minor</option>
                <option value="E7">E7</option>
              </optgroup>

              <optgroup label="F / F# Family">
                <option value="F">F major</option>
                <option value="Fm">F minor</option>
                <option value="F7">F7</option>
                <option value="F#">F# major</option>
                <option value="F#m">F# minor</option>
                <option value="F#7">F#7</option>
                <option value="Gb">Gb major</option>
                <option value="Gbm">Gb minor</option>
                <option value="Gb7">Gb7</option>
              </optgroup>

              <optgroup label="G / G# Family">
                <option value="G">G major</option>
                <option value="Gm">G minor</option>
                <option value="G7">G7</option>
                <option value="G#">G# major</option>
                <option value="G#m">G# minor</option>
                <option value="G#7">G#7</option>
                <option value="Ab">Ab major</option>
                <option value="Abm">Ab minor</option>
                <option value="Ab7">Ab7</option>
              </optgroup>

              <optgroup label="A / A# Family">
                <option value="A">A major</option>
                <option value="Am">A minor</option>
                <option value="A7">A7</option>
                <option value="A#">A# major</option>
                <option value="A#m">A# minor</option>
                <option value="A#7">A#7</option>
                <option value="Bb">Bb major</option>
                <option value="Bbm">Bb minor</option>
                <option value="Bb7">Bb7</option>
              </optgroup>

              <optgroup label="B Family">
                <option value="B">B major</option>
                <option value="Bm">B minor</option>
                <option value="B7">B7</option>
              </optgroup>
            </select>
          </div>

          <div>

            {/* Vertical Piano Chord Selector */}
            <div className="mb-6 flex flex-start flex-row">
              <div className="flex flex-col flex-start gap-2">
                {[
                  { key: 'C', label: 'C / C#' },
                  { key: 'D', label: 'D / D#' },
                  { key: 'E', label: 'E' },
                  { key: 'F', label: 'F / F#' },
                  { key: 'G', label: 'G / G#' },
                  { key: 'A', label: 'A / A#' },
                  { key: 'B', label: 'B' }
                ].map(({ key, label }) => (
                  <div key={key} className="flex  gap-2 mb-1">
                    <div className="w-20 text-left font-bold text-gray-700">{label}</div>
                    <button
                      className={`px-3 py-1 rounded bg-blue-100 hover:bg-blue-300 text-blue-900 font-semibold transition-colors`}
                      onClick={() => updateCell(selectedCell.row, selectedCell.col, 'chord', key)}
                    >
                      Maj
                    </button>
                    <button
                      className={`px-3 py-1 rounded bg-purple-100 hover:bg-purple-300 text-purple-900 font-semibold transition-colors`}
                      onClick={() => updateCell(selectedCell.row, selectedCell.col, 'chord', key + 'm')}
                    >
                      Min
                    </button>
                    <button
                      className={`px-3 py-1 rounded bg-green-100 hover:bg-green-300 text-green-900 font-semibold transition-colors`}
                      onClick={() => updateCell(selectedCell.row, selectedCell.col, 'chord', key + '7')}
                    >
                      7th
                    </button>
                    {/* Add sharp buttons if applicable */}
                    {['C', 'D', 'F', 'G', 'A'].includes(key) && (
                      <>
                        <button
                          className={`px-3 py-1 rounded bg-blue-200 hover:bg-blue-400 text-blue-900 font-semibold transition-colors`}
                          onClick={() => updateCell(selectedCell.row, selectedCell.col, 'chord', key + '#')}
                        >
                          ♯ Maj
                        </button>
                        <button
                          className={`px-3 py-1 rounded bg-purple-200 hover:bg-purple-400 text-purple-900 font-semibold transition-colors`}
                          onClick={() => updateCell(selectedCell.row, selectedCell.col, 'chord', key + '#m')}
                        >
                          ♯ Min
                        </button>
                        <button
                          className={`px-3 py-1 rounded bg-green-200 hover:bg-green-400 text-green-900 font-semibold transition-colors`}
                          onClick={() => updateCell(selectedCell.row, selectedCell.col, 'chord', key + '#7')}
                        >
                          ♯ 7th
                        </button>
                      </>
                    )}
                  </div>
                ))}
              </div>
            </div>
          </div>

          {grid[selectedCell.row][selectedCell.col].chord && (
            <div className="bg-gray-50 rounded-lg p-4">
              <h4 className="font-semibold text-gray-700 mb-2">
                Chord: {grid[selectedCell.row][selectedCell.col].chord}
              </h4>
              <div className="text-sm text-gray-600 mb-3">
                MIDI Notes: {chords[grid[selectedCell.row][selectedCell.col].chord].join(', ')}
              </div>
              <button
                onClick={() => playCell(selectedCell.row, selectedCell.col)}
                className="w-full px-4 py-2 bg-blue-500 hover:bg-blue-600 text-white rounded-lg font-semibold transition-colors"
                disabled={!isAudioReady}
              >
                Preview Cell
              </button>
            </div>
          )}
        </div>

        {/* Pattern Selection */}
        <div className="bg-white rounded-xl shadow-lg p-6">
          <h3 className="text-xl font-bold text-gray-800 mb-4">
            Picking Pattern for Cell {selectedCell.row + 1}.{selectedCell.col + 1}
          </h3>

          {/* Pattern Visualization */}
          <div className="mb-6">
            <h4 className="font-semibold text-gray-700 mb-3">Pattern Visualization</h4>
            <div className="bg-gray-50 rounded-lg p-4 overflow-x-auto">
              <div className="min-w-96">
                {[...stringNames].reverse().map((stringName, stringIndex) => (
                  <div key={stringIndex} className="flex items-center mb-2">
                    <div className="w-20 text-sm font-medium text-gray-700 text-right mr-2">
                      {stringName}
                    </div>
                    <div className="flex-1 relative">
                      <div className="h-1 bg-amber-600 rounded-full relative">
                        {getCurrentPattern(grid[selectedCell.row][selectedCell.col]).map((playedString, noteIndex) => {
                          // Map playedString to reversed index
                          const reversedIndex = stringNames.length - 1 - playedString;
                          if (reversedIndex === stringIndex) {
                            const totalNotes = getCurrentPattern(grid[selectedCell.row][selectedCell.col]).length;
                            const maxSlots = Math.max(8, totalNotes);
                            const position = (noteIndex / Math.max(1, maxSlots - 1)) * 100;
                            return (
                              <div
                                key={noteIndex}
                                className="absolute w-4 h-4 bg-blue-500 border-2 border-white rounded-full shadow-md transform -translate-y-1/2 -translate-x-1/2 flex items-center justify-center"
                                style={{ left: `${Math.min(position, 95)}%`, top: '50%' }}
                                title={`Note ${noteIndex + 1}: ${stringName}`}
                              >
                                <span className="text-xs text-white font-bold">{noteIndex + 1}</span>
                              </div>
                            );
                          }
                          return null;
                        })}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          </div>

          {/* Custom Pattern Builder */}
          <div className="mb-6">
            <div className="flex items-center justify-between mb-4">
              <h4 className="font-semibold text-gray-700">Custom Pattern Builder</h4>
              <button
                onClick={() => updateCell(selectedCell.row, selectedCell.col, 'pattern', 'custom')}
                className={`px-4 py-2 rounded-lg font-semibold transition-colors ${grid[selectedCell.row][selectedCell.col].pattern === 'custom'
                  ? 'bg-purple-500 text-white'
                  : 'bg-purple-100 hover:bg-purple-200 text-purple-800'
                  }`}
              >
                Use Custom
              </button>
            </div>

            {/* Saved Custom Patterns */}
            {Object.keys(savedCustomPatterns).length > 0 && (
              <div className="mb-4">
                <h5 className="font-medium text-gray-600 mb-2">Saved Custom Patterns</h5>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                  {Object.entries(savedCustomPatterns).map(([name, pattern]) => (
                    <div key={name} className="flex items-center gap-2">
                      <button
                        onClick={() => loadCustomPattern(pattern, name)}
                        className="flex-1 p-2 bg-purple-100 hover:bg-purple-200 text-purple-800 rounded-lg text-left text-sm font-medium transition-colors"
                      >
                        {name} ({pattern.length} notes)
                      </button>
                      <button
                        onClick={() => deleteCustomPattern(name)}
                        className="px-2 py-1 bg-red-500 hover:bg-red-600 text-white text-xs rounded"
                        title="Delete pattern"
                      >
                        ×
                      </button>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div className="bg-gray-50 rounded-lg p-4 mb-4">
              <div className="text-sm text-gray-600 mb-3 text-center">Click strings to build your pattern</div>
              <div className="space-y-2">
                {stringNames.map((stringName, stringIndex) => (
                  <div key={stringIndex} className="flex items-center">
                    <div className="w-20 text-sm font-medium text-gray-700 text-right mr-3">
                      {stringName}
                    </div>
                    <button
                      onClick={() => addToCustomPattern(stringIndex)}
                      disabled={grid[selectedCell.row][selectedCell.col].pattern !== 'custom'}
                      className={`flex-1 h-8 rounded-lg transition-colors font-mono text-sm ${grid[selectedCell.row][selectedCell.col].pattern === 'custom'
                        ? 'bg-amber-100 hover:bg-amber-200 border-2 border-amber-300 text-amber-800 cursor-pointer'
                        : 'bg-gray-200 border-2 border-gray-300 text-gray-500 cursor-not-allowed'
                        }`}
                    >
                      String {6 - stringIndex}
                    </button>
                  </div>
                ))}
              </div>
            </div>

            {grid[selectedCell.row][selectedCell.col].pattern === 'custom' && (
              <div className="bg-blue-50 rounded-lg p-4">
                <div className="flex items-center justify-between mb-2">
                  <h5 className="font-semibold text-gray-700">Current Pattern:</h5>
                  <button
                    onClick={clearCustomPattern}
                    className="px-3 py-1 bg-red-500 hover:bg-red-600 text-white text-sm rounded-lg"
                  >
                    Clear
                  </button>
                </div>
                <div className="font-mono text-sm text-gray-800 bg-white p-2 rounded border mb-3">
                  {(grid[selectedCell.row][selectedCell.col].customPattern || []).length > 0
                    ? (grid[selectedCell.row][selectedCell.col].customPattern || [])
                      .map((stringIndex, noteIndex) => `${noteIndex + 1}. String ${6 - stringIndex}`)
                      .join(', ')
                    : 'Empty - click strings above to add notes'
                  }
                </div>
                <div className="text-xs text-gray-600 mb-3">
                  Pattern length: {(grid[selectedCell.row][selectedCell.col].customPattern || []).length} notes
                </div>

                {/* Save Pattern */}
                {(grid[selectedCell.row][selectedCell.col].customPattern || []).length > 0 && (
                  <div className="flex gap-2">
                    <input
                      type="text"
                      placeholder="Pattern name..."
                      className="flex-1 px-3 py-1 border border-gray-300 rounded text-sm"
                      onKeyPress={(e) => {
                        if (e.key === 'Enter') {
                          const patternName = e.target.value.trim();
                          if (patternName) {
                            saveCustomPattern(patternName, grid[selectedCell.row][selectedCell.col].customPattern || []);
                            updateCustomPattern(selectedCell.row, selectedCell.col, grid[selectedCell.row][selectedCell.col].customPattern || [], patternName);
                            e.target.value = '';
                          }
                        }
                      }}
                    />
                    <button
                      onClick={(e) => {
                        const input = e.target.parentElement.querySelector('input');
                        const patternName = input.value.trim();
                        if (patternName) {
                          saveCustomPattern(patternName, grid[selectedCell.row][selectedCell.col].customPattern || []);
                          updateCustomPattern(selectedCell.row, selectedCell.col, grid[selectedCell.row][selectedCell.col].customPattern || [], patternName);
                          input.value = '';
                        }
                      }}
                      className="px-3 py-1 bg-green-500 hover:bg-green-600 text-white text-sm rounded-lg"
                    >
                      Save
                    </button>
                  </div>
                )}
              </div>
            )}
          </div>

          {/* Preset Patterns */}
          <div className="border-t pt-6">
            <h4 className="font-semibold text-gray-700 mb-3">Preset Patterns</h4>
            <div className="grid grid-cols-1 gap-2">
              {Object.entries(pickingPatterns).filter(([name]) => name !== 'custom').map(([patternName, pattern]) => (
                <button
                  key={patternName}
                  onClick={() => updateCell(selectedCell.row, selectedCell.col, 'pattern', patternName)}
                  className={`p-3 rounded-lg text-left font-mono transition-colors ${grid[selectedCell.row][selectedCell.col].pattern === patternName
                    ? 'bg-green-500 text-white'
                    : 'bg-gray-100 hover:bg-gray-200 text-gray-800'
                    }`}
                >
                  <div className="font-semibold text-sm">{patternName}</div>
                  <div className="text-xs opacity-75">
                    {pattern.length} notes
                  </div>
                </button>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* Current Selection Info */}
      <div className="bg-white rounded-xl shadow-lg p-6 mt-6">
        <h3 className="text-xl font-bold text-gray-800 mb-4">Current Selection</h3>
        <div className="grid md:grid-cols-2 gap-6">
          <div>
            <h4 className="font-semibold text-gray-700 mb-2">Chord: {grid[selectedCell.row][selectedCell.col].chord || 'None'}</h4>
            {grid[selectedCell.row][selectedCell.col].chord && chords[grid[selectedCell.row][selectedCell.col].chord] && (
              <div className="text-sm text-gray-600">
                MIDI Notes: {chords[grid[selectedCell.row][selectedCell.col].chord].join(', ')}
              </div>
            )}
          </div>
          <div>
            <h4 className="font-semibold text-gray-700 mb-2">Pattern: {grid[selectedCell.row][selectedCell.col].pattern === 'custom' && grid[selectedCell.row][selectedCell.col].customPatternName ? grid[selectedCell.row][selectedCell.col].customPatternName : grid[selectedCell.row][selectedCell.col].pattern}</h4>
            <div className="text-sm text-gray-600">
              {grid[selectedCell.row][selectedCell.col].pattern === 'custom'
                ? `Custom pattern: ${(grid[selectedCell.row][selectedCell.col].customPattern || [])
                  .map(stringIndex => `String ${6 - stringIndex}`).join(' → ') || 'Empty'}`
                : `Pattern: ${getCurrentPattern(grid[selectedCell.row][selectedCell.col]).length} notes`
              }
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default GuitarChordApp;