import { useIndexedDB } from "react-indexed-db-hook";
import dayjs from "dayjs";
import { crc32 } from "js-crc";


export interface StoredFile {
  id: number;
  name: string;
  type: string;
  size: number;
  blob: Blob;
  checksum: string;
  created: string;
  updated: string;
}

const useFiles = () => {
  const files = useIndexedDB("file");

  const ok = !!files;

  if (!files) {
    throw new Error("couldn't load files");
  }

  const getFileById = async (id: number) => {
    return (await files.getByID(id)) as StoredFile;
  };

  const getFileByName = async (name: string) => {
    const allFiles = await files.getAll();
    return allFiles.find((f) => f.name === name) as StoredFile;
  };

  const blobChecksum = async (blob: Blob) => {
    const str = await blob.text();
    const res = crc32(str);
    return res;
  };

  const saveFileByName = async (props: { fileName: string, content: any }) => {
    const { fileName, content } = props;
    let existing = await getFileByName(fileName);
    const updated = dayjs().toISOString();
    const blob = new Blob([JSON.stringify(content, null, 2)], { type: "application/json" });
    const size = blob.size;
    const checksum = await blobChecksum(blob);
    if (!existing) {
      console.log("Creating new file", fileName);
      const updated = dayjs().toISOString();
      const created = dayjs().toISOString();
      const type = "application/json";
      existing = {
        id: 0,
        name: fileName,
        type,
        size,
        blob,
        checksum,
        created,
        updated,
      }
      const fileId = await files.add(existing);
      existing.id = fileId;
    }
    const file = {
      ...existing,
      size,
      blob,
      checksum,
      updated,
    };
    const update = await files.update(file);

    return { file, update };
  };

  return {
    ok,
    getFileByName,
    saveFileByName,
  };
}

export default useFiles;